/**
 * The in-sandbox callback registry and timer shims.
 *
 * This JavaScript source is injected (via `context.evalCode`) into a FRESH
 * QuickJS context at sandbox init. It defines, INSIDE the sandbox realm:
 *
 *  - `globalThis.__cb` — the callback registry. Callbacks
 *    NEVER cross the host↔sandbox boundary as function references; they are
 *    STORED here and referenced across the boundary by INTEGER id. `store(fn)`
 *    returns an integer id; `resume(id, argsJson)` invokes the stored fn with
 *    JSON-decoded args; `release(id)` frees it. The map is own-property-guarded
 *    (a wire id can never resolve to a prototype member — the same
 *    prototype-pollution discipline as the parser's SUBTYPE_FIELDS dispatch).
 *    Both closures AND named-global-string callbacks (the World API's
 *    function-name convention) ride this — a name is looked up on globalThis
 *    then stored, a closure is stored directly.
 *
 *  - The timer shims `setTimeout`/`setInterval`/`clearTimeout`/
 *    `clearInterval` — they store the callback in `__cb` and hand the integer
 *    id to the HOST timer functions `__scheduleTimer(kind, cbId, ms)` /
 *    `__clearTimer(timerId)` (exposed by the host; see sandboxCore.ts). There
 *    is NO event loop in QuickJS — the host `tick(deltaMs)` decrements the
 *    timer records and calls `__cb.resume` when due. These are the modern
 *    timer tier (ms-based, real-function OR name-string callbacks, opaque
 *    numeric timer-id return); the World API's `Time.SetInterval/…` names map
 *    onto the same plumbing, and the host pumps the promise/job queue in
 *    `tick` so an `await` over a timer resolves across ticks.
 *
 * Args cross as a JSON STRING (serializable-only boundary) — the host passes
 * `argsJson`, the shim `JSON.parse`s it.
 */
export const CALLBACK_REGISTRY_BOOTSTRAP = `
(function () {
  var store = Object.create(null);
  var nextId = 1;
  globalThis.__cb = {
    store: function (fn) {
      // A named-global-string callback (the legacy World API convention) resolves to
      // its global function; a real closure is stored directly. Anything
      // non-callable is rejected (returns 0 — an id that never resumes).
      var target = fn;
      if (typeof target === 'string') {
        target = globalThis[target];
      }
      if (typeof target !== 'function') {
        return 0;
      }
      var id = nextId++;
      store[id] = target;
      return id;
    },
    resume: function (id, argsJson) {
      // Own-property guard: a wire id must never resolve to a prototype member.
      if (!Object.prototype.hasOwnProperty.call(store, id)) {
        return;
      }
      var fn = store[id];
      var args = [];
      if (typeof argsJson === 'string' && argsJson.length > 0) {
        try {
          var parsed = JSON.parse(argsJson);
          if (Array.isArray(parsed)) {
            args = parsed;
          }
        } catch (e) {
          args = [];
        }
      }
      var ret = fn.apply(undefined, args);
      // A callback (timer / onLoaded / CallAsynchronously) may be an
      // ASYNC function whose returned promise REJECTS later; that rejection would
      // otherwise be dropped silently (no host rejection tracker in emscripten-core
      // 0.32). Route it to console.error — the SAME surface a SYNC handler throw uses.
      // __reportAsyncError is defined by the World-API prelude (injected AFTER this
      // bootstrap; present by the time resume runs at tick time).
      if (ret && typeof ret.then === 'function') {
        ret.then(undefined, function (e) {
          if (typeof globalThis.__reportAsyncError === 'function') {
            globalThis.__reportAsyncError(e);
          }
        });
      }
      return ret;
    },
    release: function (id) {
      if (Object.prototype.hasOwnProperty.call(store, id)) {
        delete store[id];
      }
    },
    // The count of live stored callbacks, so a test can prove that a
    // re-registered message callback does NOT leak store entries over N
    // re-registrations. Own-property-safe key count.
    count: function () {
      return Object.keys(store).length;
    },
  };

  // Timer shims — store the callback + hand the integer id to the host.
  // The World API's Time.* (in the prelude) rides the same plumbing.
  globalThis.setTimeout = function (fn, ms) {
    var id = globalThis.__cb.store(fn);
    if (id === 0) return 0;
    return globalThis.__scheduleTimer('timeout', id, (ms | 0));
  };
  globalThis.setInterval = function (fn, ms) {
    var id = globalThis.__cb.store(fn);
    if (id === 0) return 0;
    return globalThis.__scheduleTimer('interval', id, (ms | 0));
  };
  globalThis.clearTimeout = function (timerId) {
    globalThis.__clearTimer(timerId | 0);
  };
  globalThis.clearInterval = function (timerId) {
    globalThis.__clearTimer(timerId | 0);
  };
})();
`;
