/**
 * Sandbox core. The variant-agnostic QuickJS wiring.
 *
 * CODE-SPLIT: reached ONLY via the dynamic `import('./sandboxChunk')` (the
 * browser path) or directly by node unit tests (the debug-variant path). It
 * imports `quickjs-emscripten-core` (small — the ~1 MB WASM lives in the
 * VARIANT, not here) and is NEVER statically imported by any main-bundle
 * module. `worldSession` reaches it only through the injected `SandboxLoader`.
 *
 * `createSandboxFromModule(module, options)` takes an already-built
 * `QuickJSWASMModule` and returns a `Sandbox`. `sandboxChunk.ts` builds the
 * module from the singlefile BROWSER variant (inlined WASM — offline/same-
 * origin/headless clean); unit tests build it from the singlefile CJS-DEBUG
 * variant wrapped in `TestQuickJSWASMModule` for handle-leak assertions.
 *
 * The design:
 *  - Serializable-only boundary — host functions dump argument handles to
 *    plain values (`context.dump`) and marshal returns back; function
 *    references NEVER cross.
 *  - In-sandbox callback registry (`__cb`, callbackRegistry.ts) — callbacks
 *    cross as INTEGER ids; the host stores nothing but the int.
 *  - Host drives time — `tick(deltaMs)` flushes deferred one-shots then fires
 *    due timers (QuickJS has no event loop).
 *  - Cooperative deadline — a fresh deadline interrupt handler is
 *    set on the runtime before EVERY sandbox entry (each script + each resume),
 *    so a `while(true){}` is interrupted and the render loop keeps ticking.
 *  - Deny-by-default — a fresh QuickJS context has NO host globals (fetch/XHR/
 *    window/process/console/timers). ONLY what we `expose` crosses in.
 */
import {
  type QuickJSWASMModule,
  type QuickJSContext,
  type QuickJSRuntime,
  type QuickJSHandle,
} from 'quickjs-emscripten-core';

/**
 * The minimal module surface this core uses — just `newRuntime`. Both the real
 * `QuickJSWASMModule` (the browser chunk) and `TestQuickJSWASMModule` (the node
 * leak-assertion tests) satisfy it, so the leak-tracked wrapper can be injected
 * without a structural-typing fight over private FFI internals.
 */
export type QuickJSModuleLike = Pick<QuickJSWASMModule, 'newRuntime'>;
import { CALLBACK_REGISTRY_BOOTSTRAP } from './callbackRegistry';
import { WORLD_API_PRELUDE } from './worldApiPrelude';
import type {
  Sandbox,
  SandboxOptions,
  ScriptError,
  EvaluateResult,
  HostFunction,
  SerializableValue,
  CreateEntitySpec,
  Vec3Like,
  QuatLike,
  ColorLike,
  LightPropertiesSpec,
  PhysicalPropertiesSpec,
  SkyOptionsSpec,
  EnvironmentMapOptionsSpec,
} from './sandboxTypes';

/** The shared `webverse:ls:` namespace for `LocalStorage` (deny-by-default). */
const LOCAL_STORAGE_PREFIX = 'webverse:ls:';

/**
 * Coerce a value dumped from (or bound for) the sandbox into a SERIALIZABLE
 * form. The host functions (Logging/WorldStorage/LocalStorage) receive world-controlled
 * args, so a non-serializable value must degrade sanely, NEVER crash the host
 * or a downstream `JSON.stringify`:
 *  - bigint → Number if it fits `Number.isSafeInteger`, else its String form;
 *  - symbol / function / undefined → dropped (returns `undefined`);
 *  - object/array → recursively coerced (own-enumerable keys; dropped values
 *    become `null` in arrays, omitted keys in objects); cycles are broken;
 *  - number/string/boolean/null → passed through.
 * `seen` breaks reference cycles (a circular graph must not hang the host).
 */
function toHostSafe(value: unknown, seen: WeakSet<object>): SerializableValue | undefined {
  switch (typeof value) {
    case 'number':
    case 'string':
    case 'boolean':
      return value as SerializableValue;
    case 'bigint':
      return value >= BigInt(Number.MIN_SAFE_INTEGER) && value <= BigInt(Number.MAX_SAFE_INTEGER)
        ? Number(value)
        : String(value);
    case 'symbol':
    case 'function':
    case 'undefined':
      return undefined;
    case 'object': {
      if (value === null) return null;
      if (seen.has(value as object)) return null; // break a reference cycle
      seen.add(value as object);
      if (Array.isArray(value)) {
        const out: SerializableValue[] = [];
        for (const el of value) {
          const s = toHostSafe(el, seen);
          out.push(s === undefined ? null : s);
        }
        return out;
      }
      const out: { [key: string]: SerializableValue } = {};
      for (const key of Object.keys(value as Record<string, unknown>)) {
        // Assigned as a key, `__proto__` would become the copy's prototype and not a field of it.
        if (key === '__proto__') continue;
        const s = toHostSafe((value as Record<string, unknown>)[key], seen);
        if (s !== undefined) out[key] = s;
      }
      return out;
    }
    default:
      return undefined;
  }
}

/** Default per-script deadline (ms) — generous; runs once at world load, off the hot path. */
const DEFAULT_SCRIPT_BUDGET_MS = 1000;
/** Default per tick-callback/timer deadline (ms) — tight; must not blow a frame. */
const DEFAULT_TICK_CALLBACK_BUDGET_MS = 100;
/**
 * Default per-world memory ceiling (bytes). The cooperative deadline
 * bounds CPU TIME, but NOT memory: a single large allocation (e.g.
 * `new ArrayBuffer(2e9)`) completes in one un-interruptible op and, with NO
 * limit, makes the emscripten allocator FAIL → `abort()` — a HARD, uncatchable
 * WASM termination that poisons the shared module for the whole session. A
 * runtime memory limit makes QuickJS instead raise a CATCHABLE out-of-memory
 * JS exception (a fail `VmCallResult` → `ScriptError`) before the allocator
 * aborts, so an allocation-bomb world is reported and the tab survives. 64 MB
 * is generous for world setup while capping multi-GB bombs.
 */
const DEFAULT_MEMORY_LIMIT_BYTES = 64 * 1024 * 1024;
/**
 * Default per-world stack ceiling (bytes) — defense-in-depth. QuickJS
 * already bounds deep recursion by a built-in default; setting it explicitly
 * makes the guard intentional (a `function f(){return f()}` bomb → catchable
 * "stack overflow", never a host crash). 1 MB leaves ample headroom for
 * legitimate nested marshalling while staying finite.
 */
const DEFAULT_MAX_STACK_SIZE_BYTES = 1024 * 1024;
/**
 * The per-tick cap on QuickJS microtask/job-queue draining (the sandbox's
 * event-loop model). A QuickJS sandbox has NO event loop: promises
 * and `async`/`await` create PENDING JOBS that do not run until the host calls
 * `runtime.executePendingJobs()`. `tick` pumps the queue each frame so `await`
 * / `.then` progress. This cap is MANDATORY: `executePendingJobs(-1)` drains
 * until the queue is empty, so a promise chain that synchronously re-queues
 * itself (`Promise.resolve().then(function loop(){ Promise.resolve().then(loop); })`)
 * would spin FOREVER inside one tick. A positive cap makes such a chain take
 * exactly this many bounded steps per tick and RESUME next tick — the frame
 * never hangs (the cooperative deadline is the second, finer bound around a
 * single runaway job). 1000 is ample for a legitimate world's per-frame async
 * settling while capping a pathological re-queue.
 */
export const MAX_JOBS_PER_TICK = 1000;
/**
 * The minimum per-JOB cooperative-deadline budget (ms) the
 * tick pump arms before executing a SINGLE job. The pump drains ONE job per
 * iteration (see `tick`); each started job is armed with `max(this, deadline −
 * now)` so a LEGIT reaction near the tick-budget edge always gets a full floor to
 * COMPLETE and is never interrupted mid-flight (a legit burst spills to the next
 * tick rather than corrupting a reaction). Only a job that
 * itself runs longer than its budget is a genuine runaway → interrupted +
 * reported. Small (a legit reaction is microseconds) but non-zero so a job started
 * exactly at the deadline still makes progress. Worst-case frame overshoot past the
 * single tick origin is bounded to ~this.
 */
export const MIN_JOB_BUDGET_MS = 4;
/**
 * The DISPOSE-drain WALL-CLOCK budget (ms). A drain bounded only by a PASS COUNT
 * (batches of `executePendingJobs`) is unbounded in WALL TIME for a self-requeuing
 * job graph (a promise FANOUT, `sandboxJobPumpTeardown.test.ts`): QuickJS's
 * interrupt handler only cuts off a job that ITSELF runs long enough to hit an
 * interrupt checkpoint — a fanout reaction's body (a short loop) never does — so
 * every drained job runs to completion and re-queues MORE jobs than were drained,
 * and each pass GROWS the backlog (seconds of CPU per `dispose()`). So the drain
 * takes ONE JOB AT A TIME (mirroring the tick pump's `MIN_JOB_BUDGET_MS` per-job
 * floor) and checks the clock against this budget BEFORE EVERY JOB, so `dispose()`
 * cost is a small, deterministic multiple of this budget REGARDLESS of backlog
 * size. A residual (un-drained) queue past the budget is abandoned to the guarded
 * frees below, which keep "dispose never throws" true (a large enough backlog trips
 * the `JS_FreeRuntime` assertion however it is drained). Small — a legitimate world's
 * residual pending-job count at teardown is tiny; only an adversarial/self-requeuing
 * graph ever hits this ceiling.
 */
export const DISPOSE_DRAIN_BUDGET_MS = 8;
/**
 * The dispose-drain PASS CAP, a SECONDARY bound
 * alongside `DISPOSE_DRAIN_BUDGET_MS` (distinct from `MAX_JOBS_PER_TICK`, the tick
 * pump's TOTAL-JOB budget). `dispose` runs at most this many single-job passes so a
 * pathologically fast machine (where the wall-clock budget alone would let through
 * an unreasonable job count) still has a hard ceiling.
 */
export const MAX_DISPOSE_DRAIN_PASSES = 1000;
/**
 * A SANE ceiling on the deferred one-shot queue (`deferResume`) so an
 * OFF-TICK flood of inbound network callbacks (a peer publishing app messages
 * faster than the render tick drains them) cannot grow the queue unbounded between
 * ticks — the same drop-with-warn-once discipline as the input queue
 * (QUEUE_CAP). This is a BASIC bound; per-peer rate/count caps and field
 * validation handle the full untrusted-peer threat model. Generous — a
 * legitimate world's onLoaded/timer/message deferrals never approach it.
 */
export const MAX_DEFERRED_QUEUE = 4096;

type TimerKind = 'timeout' | 'interval';
interface TimerRecord {
  cbId: number;
  kind: TimerKind;
  remainingMs: number;
  intervalMs: number | null;
}
interface DeferredRecord {
  cbId: number;
  argsJson: string;
  release: boolean;
}

/**
 * Build a `Sandbox` over an already-constructed QuickJS module. The module is
 * owned by the caller for module-level cleanup (the chunk keeps a singleton;
 * tests wrap it in TestQuickJSWASMModule for leak assertions) — this factory
 * owns the RUNTIME + CONTEXT it creates and disposes them in `dispose()`.
 */
export function createSandboxFromModule(
  module: QuickJSModuleLike,
  options: SandboxOptions = {},
): Sandbox {
  const scriptBudgetMs = options.scriptBudgetMs ?? DEFAULT_SCRIPT_BUDGET_MS;
  const tickBudgetMs = options.tickCallbackBudgetMs ?? DEFAULT_TICK_CALLBACK_BUDGET_MS;
  // ONE clock for every budget and deadline below: injectable so a test
  // can assert how a tick's budget is split without timing a real busy-wait.
  const now = options.now ?? Date.now;
  const memoryLimitBytes = options.memoryLimitBytes ?? DEFAULT_MEMORY_LIMIT_BYTES;
  const maxStackSizeBytes = options.maxStackSizeBytes ?? DEFAULT_MAX_STACK_SIZE_BYTES;

  // The World-API host services. WorldStorage is a per-world
  // in-memory Map (a FRESH sandbox per world ⇒ WORLD-SCOPED by construction —
  // set in world A, gone in world B). UUID randomness defaults to Web Crypto
  // (browser + node ≥ 16); a stub can be injected for deterministic tests.
  const worldStorage = new Map<string, string | null>();
  const localStorage = options.localStorage;
  const uuidFn =
    options.uuid ??
    (() => {
      const c: { randomUUID?: () => string } | undefined =
        typeof globalThis !== 'undefined'
          ? (globalThis as { crypto?: { randomUUID?: () => string } }).crypto
          : undefined;
      return typeof c?.randomUUID === 'function'
        ? c.randomUUID()
        : '00000000-0000-0000-0000-000000000000';
    });

  const runtime: QuickJSRuntime = module.newRuntime();
  // Bound sandbox MEMORY + STACK BEFORE creating the context — the
  // cooperative deadline only bounds CPU time; without these an allocation bomb
  // or unbounded recursion hard-aborts the WASM module. A limit of -1/0 removes
  // the respective cap (opt-out for a trusted/self-boot host). QuickJS raises a
  // CATCHABLE OOM/stack-overflow exception at the limit → `ScriptError`, never a
  // host abort. 64 MB / 1 MB are ample for legitimate world setup.
  if (memoryLimitBytes > 0) runtime.setMemoryLimit(memoryLimitBytes);
  if (maxStackSizeBytes > 0) runtime.setMaxStackSize(maxStackSizeBytes);
  const context: QuickJSContext = runtime.newContext();
  let disposed = false;

  // Host-side timer + deferred state (the sandbox holds NO host globals; time
  // is driven from here).
  const timers = new Map<number, TimerRecord>();
  const deferred: DeferredRecord[] = [];
  let deferredDropWarned = false;
  // Raw CODE-STRING dispatches queued OFF-TICK (the corpus's
  // `onJoinedAction`, fired by the async network join) and drained on the next
  // `tick` via `dispatch` (evalCode under the tick deadline; no script runs
  // outside a tick).
  const deferredDispatch: { code: string; label: string }[] = [];
  let nextTimerId = 1;

  // Long-lived handles into the sandbox realm (disposed in dispose()). We look
  // up __cb + its resume/release once so `tick` can call back in cheaply, and
  // JSON.parse so host→sandbox object marshalling is faithful.
  const longLived: QuickJSHandle[] = [];

  /** Set a FRESH cooperative deadline before a sandbox entry. */
  const armDeadline = (budgetMs: number): void => {
    const deadline = now() + budgetMs;
    runtime.setInterruptHandler(() => now() > deadline);
  };

  // Inject the in-sandbox callback registry + timer shims BEFORE exposing
  // the host timer functions the shims call. The bootstrap is TRUSTED host code
  // — run it with the interrupt handler DISABLED (never time-box our own
  // scaffolding by the user's — possibly tiny — script budget; the deadline
  // guards UNTRUSTED world scripts only).
  {
    runtime.setInterruptHandler(() => false);
    const r = context.evalCode(CALLBACK_REGISTRY_BOOTSTRAP, 'callback-registry.js');
    if (r.error) {
      const err = context.dump(r.error);
      r.error.dispose();
      // Should never happen (the bootstrap is ours) — fail loud on init.
      runtime.setInterruptHandler(() => false);
      context.dispose();
      runtime.dispose();
      throw new Error(`[sandbox] callback-registry bootstrap failed: ${String(err)}`);
    }
    r.value.dispose();
  }

  const jsonHandle = context.getProp(context.global, 'JSON');
  const jsonParseHandle = context.getProp(jsonHandle, 'parse');
  const cbHandle = context.getProp(context.global, '__cb');
  const cbResumeHandle = context.getProp(cbHandle, 'resume');
  const cbReleaseHandle = context.getProp(cbHandle, 'release');
  longLived.push(jsonHandle, jsonParseHandle, cbHandle, cbResumeHandle, cbReleaseHandle);

  /**
   * Marshal a serializable host value INTO a fresh context handle. Primitives
   * map directly; arrays/objects go through the VM's own JSON.parse (faithful,
   * and keeps the boundary serializable — no live references). The caller owns
   * (and disposes) the returned handle.
   */
  const marshalIn = (value: SerializableValue | undefined): QuickJSHandle => {
    if (value === null || value === undefined) return context.undefined;
    switch (typeof value) {
      case 'number':
        return context.newNumber(value);
      case 'string':
        return context.newString(value);
      case 'boolean':
        return value ? context.true : context.false;
      default: {
        // array or plain object — parse from JSON inside the VM. Guard the
        // stringify (circular/oversized → undefined, never a host throw); the
        // value has already been coerced serializable-safe by the caller.
        let json: string;
        try {
          json = JSON.stringify(value);
        } catch {
          return context.undefined;
        }
        if (json === undefined) return context.undefined;
        const jsonStr = context.newString(json);
        const parsed = context.callFunction(jsonParseHandle, jsonHandle, jsonStr);
        jsonStr.dispose();
        if (parsed.error) {
          parsed.error.dispose();
          return context.undefined;
        }
        return parsed.value;
      }
    }
  };

  /** Whether an intrinsic (context-owned) handle must NOT be disposed. */
  const isIntrinsic = (h: QuickJSHandle): boolean =>
    h === context.undefined || h === context.null || h === context.true || h === context.false;

  const disposeIfOwned = (h: QuickJSHandle): void => {
    if (!isIntrinsic(h)) h.dispose();
  };

  /** Resume an in-sandbox callback by integer id with JSON-encoded args (deadline-guarded). */
  const resumeCallback = (cbId: number, argsJson: string): ScriptError | null => {
    if (disposed) return null;
    armDeadline(tickBudgetMs);
    const idHandle = context.newNumber(cbId);
    const argsHandle = context.newString(argsJson);
    const res = context.callFunction(cbResumeHandle, cbHandle, idHandle, argsHandle);
    idHandle.dispose();
    argsHandle.dispose();
    if (res.error) {
      const error = describeError(context, res.error, `callback#${cbId}`);
      res.error.dispose();
      return error;
    }
    res.value.dispose();
    return null;
  };

  /** Release an in-sandbox callback id (free the stored fn). */
  const releaseCallback = (cbId: number): void => {
    if (disposed) return;
    // Not user code — a small fixed op; still guard it.
    armDeadline(tickBudgetMs);
    const idHandle = context.newNumber(cbId);
    const res = context.callFunction(cbReleaseHandle, cbHandle, idHandle);
    idHandle.dispose();
    if (res.error) res.error.dispose();
    else res.value.dispose();
  };

  /** Report a resumed-callback error to the log (the world stays live). */
  const reportCallbackError = (error: ScriptError | null): void => {
    // There is no session wiring here; the caller (worldSession) owns the
    // scriptReport. A tick-time error is logged via onLog if present so the
    // test bridge can observe it, and dropped so the frame proceeds.
    if (error && options.onLog) {
      options.onLog(`[error] ${error.source}: ${error.message}`);
    }
  };

  // --- Expose the host functions. ---

  const expose = (name: string, fn: HostFunction): void => {
    if (disposed) return;
    const fnHandle = context.newFunction(name, (...argHandles: QuickJSHandle[]) => {
      // Serializable-only boundary: dump each arg handle and COERCE it
      // serializable-safe (bigint/symbol/function/undefined → degrade, never
      // crash the host). The
      // incoming handles are owned by the CALLER (do NOT dispose them here).
      const args = argHandles.map((h): SerializableValue => {
        try {
          const coerced = toHostSafe(context.dump(h), new WeakSet());
          return coerced === undefined ? null : coerced;
        } catch {
          return null;
        }
      });
      let result: SerializableValue | void;
      try {
        result = fn(...args);
      } catch (err) {
        // A host-side throw becomes a sandbox exception (never crashes the host).
        const message = err instanceof Error ? err.message : String(err);
        return { error: context.newError(message) };
      }
      // Coerce the RETURN too — a host fn returning a bigint/symbol/function
      // degrades to undefined rather than throwing in marshalIn's JSON path.
      const safe = toHostSafe(result, new WeakSet());
      return marshalIn(safe === undefined ? null : safe);
    });
    context.setProp(context.global, name, fnHandle);
    fnHandle.dispose();
  };

  // The World-API `Logging.*` host bridge. The prelude's
  // `Logging.Log/LogWarning/...` call this
  // with the mapped level; the host routes it to the leveled runtime
  // logger (`logSink`) AND to the raw `onLog` passthrough (the scriptReport
  // testLog observation surface). `level` is coerced to a string in the prelude.
  expose('__log', (level, msg) => {
    const message = String(msg ?? '');
    const lvl = level === 'debug' || level === 'warning' || level === 'error' ? level : 'default';
    options.logSink?.(lvl, message);
    options.onLog?.(message);
  });

  // UUID randomness (QuickJS has no crypto). The prelude
  // `UUID.NewUUID()` calls this.
  expose('__uuid', () => uuidFn());

  // WorldStorage host bridge (world-scoped: the per-world Map).
  expose('__worldStorageSet', (key, value) => {
    worldStorage.set(String(key), value === null || value === undefined ? null : String(value));
  });
  expose('__worldStorageGet', (key) => {
    const k = String(key);
    return worldStorage.has(k) ? worldStorage.get(k) ?? null : null;
  });

  // LocalStorage host bridge (persistent; namespaced under `webverse:ls:`
  // so a world cannot reach the host app's own keys). The backend the session
  // hands in keeps each source's values apart (scene/sourceStorage.ts). A
  // missing backend (node/unit without a stub) is a safe no-op.
  expose('__localStorageSet', (key, value) => {
    localStorage?.setItem(LOCAL_STORAGE_PREFIX + String(key), value === null || value === undefined ? '' : String(value));
  });
  expose('__localStorageGet', (key) => {
    return localStorage?.getItem(LOCAL_STORAGE_PREFIX + String(key)) ?? null;
  });
  expose('__localStorageRemove', (key) => {
    localStorage?.removeItem(LOCAL_STORAGE_PREFIX + String(key));
  });

  // The SCENE-TOUCHING Entity/World/Camera host bridges. These
  // forward dumped id strings + plain-data ({x,y,z}/{x,y,z,w}/{r,g,b,a}) +
  // booleans to the injected `options.entityApi` (the CODE-SPLIT scriptEntityApi,
  // the ONLY Babylon-touching layer). THE HANDLE-AS-ID INVARIANT: a bridge
  // returns ONLY entity-ID strings, id arrays, plain-data, or booleans — NEVER a
  // live Babylon node (toHostSafe is the backstop; the bridge contract is the
  // real guard). Absent `entityApi` → sane null/no-op (a scriptless-scene world).
  const entityApi = options.entityApi;
  const asBool = (v: SerializableValue): boolean => v === true;
  const asVec3 = (v: SerializableValue): Vec3Like => {
    const o = (v && typeof v === 'object' ? v : {}) as Record<string, unknown>;
    return {
      x: typeof o.x === 'number' ? o.x : 0,
      y: typeof o.y === 'number' ? o.y : 0,
      z: typeof o.z === 'number' ? o.z : 0,
    };
  };
  const asQuat = (v: SerializableValue): QuatLike => {
    const o = (v && typeof v === 'object' ? v : {}) as Record<string, unknown>;
    return {
      x: typeof o.x === 'number' ? o.x : 0,
      y: typeof o.y === 'number' ? o.y : 0,
      z: typeof o.z === 'number' ? o.z : 0,
      w: typeof o.w === 'number' ? o.w : 1,
    };
  };
  // A script `Color` ({r,g,b,a}) crosses as plain data (no live
  // node). Missing channels default (r/g/b→0.5, a→1); the host guards further.
  const asColor = (v: SerializableValue): ColorLike => {
    const o = (v && typeof v === 'object' ? v : {}) as Record<string, unknown>;
    return {
      r: typeof o.r === 'number' ? o.r : 0.5,
      g: typeof o.g === 'number' ? o.g : 0.5,
      b: typeof o.b === 'number' ? o.b : 0.5,
      a: typeof o.a === 'number' ? o.a : 1,
    };
  };
  // A LightEntity.SetLightProperties spec ({color?,intensity?,
  // range?,...}) crosses as plain data. Coerce the shape the host expects.
  const asLightProps = (v: SerializableValue): LightPropertiesSpec => {
    const o = (v && typeof v === 'object' ? v : {}) as Record<string, unknown>;
    const spec: LightPropertiesSpec = {};
    if (o.color && typeof o.color === 'object') spec.color = asColor(o.color as SerializableValue);
    if (typeof o.intensity === 'number') spec.intensity = o.intensity;
    if (typeof o.range === 'number') spec.range = o.range;
    if (typeof o.innerSpotAngle === 'number') spec.innerSpotAngle = o.innerSpotAngle;
    if (typeof o.outerSpotAngle === 'number') spec.outerSpotAngle = o.outerSpotAngle;
    if (typeof o.temperature === 'number') spec.temperature = o.temperature;
    return spec;
  };
  // An Environment.SetSky spec: the sky profile's attributes, own-property
  // guarded; a colour crosses as plain {r,g,b,a}.
  const asSkyOptions = (v: SerializableValue): SkyOptionsSpec => {
    const o = (v && typeof v === 'object' ? v : {}) as Record<string, unknown>;
    const spec: SkyOptionsSpec = {};
    for (const k of ['zenith', 'horizon', 'groundColor', 'sunColor'] as const) {
      if (o[k] && typeof o[k] === 'object') spec[k] = asColor(o[k] as SerializableValue);
    }
    for (const k of ['blend', 'groundHeight', 'groundFade', 'sunDiameter', 'sunElevation', 'sunAzimuth'] as const) {
      if (typeof o[k] === 'number') spec[k] = o[k] as number;
    }
    for (const k of ['groundEnabled', 'sunEnabled'] as const) {
      if (typeof o[k] === 'boolean') spec[k] = o[k] as boolean;
    }
    return spec;
  };
  // An Environment.SetEnvironmentMap spec: the environment profile's tuning attributes.
  const asEnvironmentMapOptions = (v: SerializableValue): EnvironmentMapOptionsSpec => {
    const o = (v && typeof v === 'object' ? v : {}) as Record<string, unknown>;
    const spec: EnvironmentMapOptionsSpec = {};
    for (const k of ['intensity', 'diffuse', 'specular', 'glazingBoost', 'glazingF0'] as const) {
      if (typeof o[k] === 'number') spec[k] = o[k] as number;
    }
    if (o.punctualLights === 'keep' || o.punctualLights === 'exclude') spec.punctualLights = o.punctualLights;
    return spec;
  };
  // A CharacterEntity.SetPhysicalProperties spec ({angularDrag?,
  // centerOfMass?,drag?,gravitational?,mass?}) crosses as plain data. Own-property-
  // guarded (a hostile props object never pollutes — read only the known fields).
  const asPhysicalProps = (v: SerializableValue): PhysicalPropertiesSpec => {
    const o = (v && typeof v === 'object' ? v : {}) as Record<string, unknown>;
    const spec: PhysicalPropertiesSpec = {};
    if (typeof o.angularDrag === 'number') spec.angularDrag = o.angularDrag;
    if (typeof o.drag === 'number') spec.drag = o.drag;
    if (typeof o.mass === 'number') spec.mass = o.mass;
    if (typeof o.gravitational === 'boolean') spec.gravitational = o.gravitational;
    if (o.centerOfMass && typeof o.centerOfMass === 'object') {
      spec.centerOfMass = asVec3(o.centerOfMass as SerializableValue);
    }
    return spec;
  };

  // Factory: mint a hollow handle synchronously (returns the id); `onLoaded`
  // (integer __cb id) fires on a SUBSEQUENT tick via deferResume (the id never
  // leaves the sandbox for the callback — the prelude reconstructs the handle).
  expose('__entityCreate', (spec, cbId, errCbId) => {
    if (!entityApi || !spec || typeof spec !== 'object') return null;
    const onLoaded =
      typeof cbId === 'number' && cbId > 0 ? (): void => deferResume(cbId, [], true) : undefined;
    // The ASYNC-failure channel. When the prelude's promise
    // `createAsync` supplies an error cbId, an async mesh-load failure resumes it
    // (with the message) so the promise REJECTS catchably. Absent (the sync path) →
    // undefined → createEntity keeps the legacy World API's onLoaded-on-failure
    // behavior, which existing world scripts rely on.
    const onError =
      typeof errCbId === 'number' && errCbId > 0
        ? (message: string): void => deferResume(errCbId, [String(message ?? 'entity load failed')], true)
        : undefined;
    return entityApi.createEntity(spec as unknown as CreateEntitySpec, onLoaded, onError);
  });
  expose('__entityGet', (id) => entityApi?.get(String(id)) ?? null);
  expose('__entityGetByTag', (tag) => entityApi?.getByTag(String(tag)) ?? null);
  expose('__entityGetAll', () => entityApi?.getAll() ?? []);
  expose('__entityGetTag', (id) => entityApi?.getTag(String(id)) ?? null);
  expose('__entityGetPosition', (id, local) => entityApi?.getPosition(String(id), asBool(local)) ?? null);
  expose('__entitySetPosition', (id, pos, local) => entityApi?.setPosition(String(id), asVec3(pos), asBool(local)) ?? false);
  expose('__entityGetRotation', (id, local) => entityApi?.getRotation(String(id), asBool(local)) ?? null);
  expose('__entitySetRotation', (id, rot, local) => entityApi?.setRotation(String(id), asQuat(rot), asBool(local)) ?? false);
  expose('__entityGetScale', (id) => entityApi?.getScale(String(id)) ?? null);
  expose('__entitySetScale', (id, scale) => entityApi?.setScale(String(id), asVec3(scale)) ?? false);
  // Transform accessors (plain-data snapshot + size + euler; NO live
  // node crosses — toHostSafe is the backstop, the bridge contract is plain data).
  expose('__entityGetTransform', (id) => (entityApi?.getTransform(String(id)) ?? null) as SerializableValue);
  expose('__entityGetSize', (id) => entityApi?.getSize(String(id)) ?? null);
  expose('__entitySetSize', (id, size) => entityApi?.setSize(String(id), asVec3(size)) ?? false);
  expose('__entityGetEulerRotation', (id, local) => entityApi?.getEulerRotation(String(id), asBool(local)) ?? null);
  expose('__entitySetEulerRotation', (id, euler, local) => entityApi?.setEulerRotation(String(id), asVec3(euler), asBool(local)) ?? false);
  expose('__entityGetParent', (id) => entityApi?.getParent(String(id)) ?? null);
  expose('__entitySetParent', (id, parentId) => entityApi?.setParent(String(id), parentId === null || parentId === undefined ? null : String(parentId)) ?? false);
  expose('__entityGetChildren', (id) => entityApi?.getChildren(String(id)) ?? []);
  expose('__entityGetVisibility', (id) => entityApi?.getVisibility(String(id)) ?? false);
  expose('__entitySetVisibility', (id, visible) => entityApi?.setVisibility(String(id), asBool(visible)) ?? false);
  expose('__entityGetHighlight', (id) => entityApi?.getHighlight(String(id)) ?? false);
  expose('__entitySetHighlight', (id, hl) => entityApi?.setHighlight(String(id), asBool(hl)) ?? false);
  expose('__entityDelete', (id) => entityApi?.delete(String(id)) ?? false);
  expose('__entityCompare', (a, b) => entityApi?.compare(String(a), String(b)) ?? false);
  expose('__worldGetQueryParam', (key) => entityApi?.worldGetQueryParam(String(key)) ?? null);
  expose('__worldLoadWorld', (url) => {
    entityApi?.worldLoadWorld(String(url));
  });
  expose('__worldLoadWebPage', (url) => {
    entityApi?.worldLoadWebPage(String(url));
  });
  expose('__worldGetLoadState', () => entityApi?.worldGetLoadState() ?? 'unloaded');
  expose('__cameraGetPosition', (local) => entityApi?.cameraGetPosition(asBool(local)) ?? null);
  expose('__cameraSetPosition', (pos, local) => entityApi?.cameraSetPosition(asVec3(pos), asBool(local)) ?? false);
  expose('__cameraGetRotation', (local) => entityApi?.cameraGetRotation(asBool(local)) ?? null);
  expose('__cameraSetRotation', (rot, local) => entityApi?.cameraSetRotation(asQuat(rot), asBool(local)) ?? false);

  // The GROWTH-TIER bridges. Environment.* is WORLD-LEVEL (no entity
  // id — keyed to the active world's environment, like __worldGetQueryParam);
  // the light + interaction-state accessors key by entity id. Babylon-free —
  // forward dumped strings/plain-data to the injected host (absent → false/null).
  expose('__environmentSetSkyTexture', (url) => entityApi?.environmentSetSkyTexture(String(url)) ?? false);
  expose('__environmentSetSolidColorSky', (color) => entityApi?.environmentSetSolidColorSky(asColor(color)) ?? false);
  expose('__environmentSetSky', (options) => entityApi?.environmentSetSky(asSkyOptions(options)) ?? false);
  expose('__environmentSetEnvironmentMap', (src, options) =>
    entityApi?.environmentSetEnvironmentMap(String(src), asEnvironmentMapOptions(options)) ?? false,
  );
  expose('__lightSetType', (id, type) => entityApi?.lightSetType(String(id), String(type)) ?? false);
  expose('__lightSetProperties', (id, props) => entityApi?.lightSetProperties(String(id), asLightProps(props)) ?? false);
  expose('__entitySetInteractionState', (id, state) => entityApi?.entitySetInteractionState(String(id), String(state)) ?? false);
  expose('__entityGetInteractionState', (id) => entityApi?.entityGetInteractionState(String(id)) ?? null);

  // The remaining-entity-factory NON-create bridges (create rides
  // __entityCreate with the growth-tier kinds + plain-data spec fields). Babylon-
  // free; forward dumped strings/ids to the injected host (absent → false/null).
  // SetText/GetText drive a `text`/`input` entity's live DynamicTexture glyph
  // content; the canvas Make*/IsScreen bridges are the WORLD-SPACE degrade.
  expose('__entitySetText', (id, text) => entityApi?.entitySetText(String(id), String(text ?? '')) ?? false);
  expose('__entityGetText', (id) => entityApi?.entityGetText(String(id)) ?? null);
  expose('__canvasMakeScreen', (id) => entityApi?.canvasMakeScreenCanvas(String(id)) ?? false);
  expose('__canvasMakeWorld', (id) => entityApi?.canvasMakeWorldCanvas(String(id)) ?? false);
  expose('__canvasIsScreen', (id) => entityApi?.canvasIsScreenCanvas(String(id)) ?? false);

  // The Input POLLING bridges (continuous move/look ride the
  // scriptInputDispatcher, NOT here). Babylon-free; forward to the injected host.
  // The returns cross as PLAIN data (a {x,y}/bool/hit-object/null — NEVER a live
  // node/event; toHostSafe is the backstop). Absent entityApi → sane zero/false/null.
  expose('__inputGetMoveValue', () => (entityApi?.inputGetMoveValue() ?? { x: 0, y: 0 }) as SerializableValue);
  expose('__inputGetLookValue', () => (entityApi?.inputGetLookValue() ?? { x: 0, y: 0 }) as SerializableValue);
  expose('__inputGetKeyValue', (key) => entityApi?.inputGetKeyValue(String(key)) ?? false);
  expose('__inputGetPointerRaycast', () => (entityApi?.inputGetPointerRaycast() ?? null) as SerializableValue);
  expose('__inputIsVR', () => entityApi?.inputIsVR() ?? false);

  // The CAMERA & RIG FOLLOWER bridges (the third-person camera
  // chain). Babylon-free; the follow TARGET crosses as an entity id STRING
  // (handle-as-id — NO live node) + an optional plain {x,y,z} offset; the host
  // resolves + drives the per-frame follow. Absent entityApi → false. Note the
  // follow DIRECTIONS, which world scripts depend on: attach/place = camera-
  // follows-entity; the add-follower calls = entity-follows-camera/rig.
  expose('__cameraAttachToEntity', (id, offset) =>
    entityApi?.cameraAttachToEntity(
      id === null || id === undefined ? null : String(id),
      offset === null || offset === undefined ? undefined : asVec3(offset),
    ) ?? false,
  );
  expose('__cameraAddFollower', (id) => entityApi?.cameraAddFollower(String(id)) ?? false);
  expose('__cameraRemoveFollower', (id) => entityApi?.cameraRemoveFollower(String(id)) ?? false);
  expose('__entityPlaceCameraOn', (id) => entityApi?.entityPlaceCameraOn(String(id)) ?? false);
  expose('__inputAddRigFollower', (id) => entityApi?.inputAddRigFollower(String(id)) ?? false);
  expose('__inputRemoveRigFollower', (id) => entityApi?.inputRemoveRigFollower(String(id)) ?? false);

  // The CHARACTER PHYSICS & MOTION bridges (KINEMATIC degrade). Babylon-
  // free; the displacement / props cross as PLAIN data (a {x,y,z} / a physical-props
  // object — NEVER a live node; toHostSafe is the backstop). The host guards the id
  // names a character (else false/null). Absent entityApi → false/null.
  expose('__characterMove', (id, v) => entityApi?.characterMove(String(id), asVec3(v)) ?? false);
  expose('__characterJump', (id, amount, discardIfFalling) =>
    entityApi?.characterJump(
      String(id),
      typeof amount === 'number' ? amount : NaN,
      discardIfFalling === undefined ? true : discardIfFalling === true,
    ) ?? false,
  );
  expose('__characterSetPhysicalProperties', (id, props) =>
    entityApi?.characterSetPhysicalProperties(String(id), asPhysicalProps(props)) ?? false,
  );
  expose('__characterGetPhysicalProperties', (id) =>
    (entityApi?.characterGetPhysicalProperties(String(id)) ?? null) as SerializableValue,
  );

  // ClientHints and Chat (the client-hints profile's Script surface).
  // Plain strings cross; OnMessage is PERSISTENT (release=false), the prior
  // registration released on a re-register.
  const peopleHost = options.peopleHost;
  expose('__hintsGet', (name) => peopleHost?.hintsGet(String(name)) ?? null);
  expose('__hintsSet', (name, value) => peopleHost?.hintsSet(String(name), String(value)) ?? false);
  expose('__chatPost', (text) => peopleHost?.chatPost(String(text ?? '')) ?? false);
  let chatCb: { id: number; off: () => void } | undefined;
  expose('__chatOnMessage', (cbId) => {
    if (!peopleHost || typeof cbId !== 'number' || cbId <= 0) return false;
    const off = peopleHost.onChat((name, text) => deferResume(cbId, [String(name ?? ''), String(text ?? '')], false));
    if (chatCb) {
      chatCb.off();
      if (chatCb.id !== cbId) releaseCallback(chatCb.id);
    }
    chatCb = { id: cbId, off };
    return true;
  });

  // Dock (the same Script surface): a tool's name and picture cross as plain
  // strings and its press as a PERSISTENT callback id, released when the
  // tool goes. The host decides whether there is room for it.
  const dockCbs = new Map<string, number>();
  const dock = () => peopleHost?.dock?.();
  expose('__dockAdd', (name, picture, cbId) => {
    const d = dock();
    if (!d || typeof cbId !== 'number' || cbId <= 0) return null;
    const id = d.addTool(String(name ?? ''), picture == null ? null : String(picture), () => deferResume(cbId, [], false));
    if (id === null) return null;
    dockCbs.set(id, cbId);
    return id;
  });
  expose('__dockRemove', (id) => {
    const key = String(id ?? '');
    const gone = dock()?.removeTool(key) ?? false;
    const cbId = dockCbs.get(key);
    if (cbId !== undefined) {
      dockCbs.delete(key);
      releaseCallback(cbId);
    }
    return gone;
  });
  expose('__dockClear', () => {
    dock()?.clearTools();
    for (const cbId of dockCbs.values()) releaseCallback(cbId);
    dockCbs.clear();
    return true;
  });

  // The action bus (VEML 4.0 §8). One persistent delivery callback
  // for the whole script side: `__actionsInit` hands its id over once; a
  // fired action the script handles comes back as `deferResume(id, [name,
  // data], false)` on the next tick. `__actionsOn/Off` only inform the host
  // which names have handlers; `__actionsFire` carries name + plain data out.
  const actionsHost = options.actionsHost;
  expose('__actionsInit', (cbId) => {
    if (!actionsHost || typeof cbId !== 'number' || cbId <= 0) return false;
    actionsHost.init(cbId);
    return true;
  });
  expose('__actionsOn', (name) => actionsHost?.on(String(name)) ?? false);
  expose('__actionsOff', (name) => {
    actionsHost?.off(String(name));
  });
  expose('__actionsFire', (name, data) => actionsHost?.fire(String(name), data ?? null) ?? false);


  // Timer PLUMBING host functions the timer shims call (callbackRegistry.ts).
  expose('__scheduleTimer', (kind, cbId, ms) => {
    if (typeof cbId !== 'number' || cbId === 0) return 0;
    const timerKind: TimerKind = kind === 'interval' ? 'interval' : 'timeout';
    const delay = typeof ms === 'number' && ms > 0 ? ms : 0;
    const timerId = nextTimerId++;
    timers.set(timerId, {
      cbId,
      kind: timerKind,
      remainingMs: delay,
      intervalMs: timerKind === 'interval' ? delay : null,
    });
    return timerId;
  });
  expose('__clearTimer', (timerId) => {
    if (typeof timerId !== 'number') return null;
    const rec = timers.get(timerId);
    if (rec) {
      timers.delete(timerId);
      releaseCallback(rec.cbId);
    }
    return null;
  });

  // Inject the World-API PRELUDE (WorldTypes/Logging/Time/Context/
  // Storage) AFTER the host bridges above are exposed (it wraps them). TRUSTED
  // host scaffolding — run with the interrupt handler DISABLED (never time-box
  // our own prelude by a world's script budget), exactly like the callback
  // bootstrap. The prelude is CODE-SPLIT-safe (a string const in the chunk).
  {
    runtime.setInterruptHandler(() => false);
    const r = context.evalCode(WORLD_API_PRELUDE, 'world-api-prelude.js');
    if (r.error) {
      const err = context.dump(r.error);
      r.error.dispose();
      context.dispose();
      runtime.dispose();
      throw new Error(`[sandbox] world-api prelude failed: ${String(err)}`);
    }
    r.value.dispose();
  }

  // A long-lived handle to the prelude's `__guardAsync` so
  // `dispatch` can route an ASYNC input/on-load handler's rejection to
  // console.error (an async handler that throws is logged like its sync twin).
  const guardAsyncHandle = context.getProp(context.global, '__guardAsync');
  longLived.push(guardAsyncHandle);

  // --- The public Sandbox surface. ---

  const runScript = (source: string, sourceLabel: string): ScriptError | null => {
    if (disposed) return null;
    armDeadline(scriptBudgetMs);
    const r = context.evalCode(source, sourceLabel);
    if (r.error) {
      const error = describeError(context, r.error, sourceLabel);
      r.error.dispose();
      return error;
    }
    r.value.dispose();
    return null;
  };

  const evaluate = (expression: string): EvaluateResult => {
    if (disposed) {
      return { ok: false, error: { source: '(disposed)', message: 'sandbox disposed' } };
    }
    armDeadline(scriptBudgetMs);
    const r = context.evalCode(expression, '(evaluate)');
    if (r.error) {
      const error = describeError(context, r.error, '(evaluate)');
      r.error.dispose();
      return { ok: false, error };
    }
    const value = context.dump(r.value) as SerializableValue;
    r.value.dispose();
    return { ok: true, value };
  };

  // Fire-and-forget dispatch of a substituted inputevent /
  // on-load-event / button-on-click expression, evaluated as script under a
  // per-callback deadline. The return value
  // is DROPPED; a throw / deadline-interrupt is returned as a ScriptError so
  // the host can log it and keep running (dropped-not-fatal). Arms the SHORTER
  // tick-callback budget (an input handler is a per-frame callback, not a
  // one-time script) so a runaway handler cannot blow a frame.
  const dispatch = (expression: string, label: string): ScriptError | null => {
    if (disposed) return null;
    armDeadline(tickBudgetMs);
    const r = context.evalCode(expression, label);
    if (r.error) {
      const error = describeError(context, r.error, label);
      r.error.dispose();
      return error;
    }
    // If the dispatched handler is ASYNC and its promise rejects,
    // route it to console.error via the prelude's `__guardAsync` (else a bare async
    // handler rejection is dropped silently — no host rejection tracker). A SYNC
    // throw is unchanged (handled above as `r.error`). Best-effort: never let the
    // guard itself throw into the host.
    if (guardAsyncHandle.alive) {
      const g = context.callFunction(guardAsyncHandle, context.undefined, r.value);
      if (g.error) g.error.dispose();
      else g.value.dispose();
    }
    r.value.dispose();
    return null;
  };

  const deferResume = (cbId: number, args: SerializableValue[], release = true): void => {
    if (disposed) return;
    // A SANE queue cap (drop-with-warn-once, the input queue's QUEUE_CAP
    // discipline). An off-tick inbound-message flood (a hostile/buggy peer) cannot
    // grow the deferred queue unbounded between ticks; a persistent (release=false)
    // network callback that would overflow is dropped, NOT fatal. A legitimate
    // world never approaches MAX_DEFERRED_QUEUE. Per-peer limits live in the net layer.
    if (deferred.length >= MAX_DEFERRED_QUEUE) {
      if (!deferredDropWarned) {
        deferredDropWarned = true;
        options.onLog?.(
          `[sandbox] deferred-callback queue at cap (${MAX_DEFERRED_QUEUE}) — dropping excess.`,
        );
      }
      return;
    }
    deferred.push({ cbId, argsJson: JSON.stringify(args ?? []), release });
  };

  // Queue a raw code string for on-tick `dispatch` (the corpus's
  // `onJoinedAction` is a code STRING run as script).
  // Deferred to a tick because no script runs off-tick; a
  // throw/deadline-interrupt is reported + dropped-not-fatal (the dispatch path).
  const deferDispatch = (code: string, label: string): void => {
    if (disposed) return;
    if (deferredDispatch.length >= MAX_DEFERRED_QUEUE) return; // same sane bound
    deferredDispatch.push({ code, label });
  };

  const tick = (deltaMs: number): void => {
    if (disposed) return;
    const dt = typeof deltaMs === 'number' && deltaMs > 0 ? deltaMs : 0;
    // ONE wall-clock origin for the WHOLE tick. Steps 1-2 (deferred
    // flush + timers) spend real time; step-3's job pump gets the REMAINING budget
    // measured from here, NOT a fresh full tickBudgetMs, so the worst-case frame is
    // bounded to ~one tick budget (plus the per-job floor) rather than
    // timers + a whole extra tick budget.
    const tickStart = now();

    // (1) Flush deferred one-shots (entity onLoaded rides this; the inbound
    // message/presence callbacks ride this as PERSISTENT — release=false —
    // deferrals).
    if (deferred.length > 0) {
      const pending = deferred.splice(0, deferred.length);
      for (const d of pending) {
        reportCallbackError(resumeCallback(d.cbId, d.argsJson));
        if (d.release) releaseCallback(d.cbId);
      }
    }

    // (1b) Drain any raw CODE-STRING dispatches queued off-tick (the
    // corpus's `onJoinedAction`, fired by the async network join). Runs verbatim
    // under the tick deadline via `dispatch`; a throw/interrupt
    // is reported + dropped-not-fatal — the session survives.
    if (deferredDispatch.length > 0) {
      const pendingDispatch = deferredDispatch.splice(0, deferredDispatch.length);
      for (const d of pendingDispatch) {
        if (disposed) return;
        reportCallbackError(dispatch(d.code, d.label));
      }
    }

    // (2) Advance timers (decrement each by the frame delta, run those due).
    if (timers.size > 0) {
      for (const [timerId, rec] of [...timers]) {
        if (disposed) return;
        rec.remainingMs -= dt;
        if (rec.remainingMs > 0) continue;
        const err = resumeCallback(rec.cbId, '[]');
        reportCallbackError(err);
        if (rec.kind === 'timeout' || err?.interrupted) {
          // A one-shot fires once; an INTERVAL whose callback OVERRAN the
          // per-tick deadline is DROPPED, not re-armed: a
          // runaway `setInterval(() => while(true){})` must not burn the full
          // tick budget on EVERY frame forever (a sustained ~10fps cap). A
          // callback that merely THREW (not interrupted) keeps firing —
          // JS-faithful setInterval semantics.
          timers.delete(timerId);
          releaseCallback(rec.cbId);
        } else {
          // re-arm the interval (carry any overshoot forward)
          rec.remainingMs += rec.intervalMs ?? 0;
          // guard against a zero-interval spin within a single tick
          if ((rec.intervalMs ?? 0) <= 0) rec.remainingMs = 0.0001;
        }
      }
    }

    // (3) PUMP the QuickJS microtask/job queue (the sandbox's
    // event-loop model). Promises + async/await create pendingJobs that DON'T
    // execute until the host runs them; without this, an `await` hangs FOREVER
    // (QuickJS has no event loop). Run AFTER the deferred flush + timers so a
    // resolve QUEUED this tick runs this tick: an entity `onLoaded` resolving a
    // `MeshEntity.CreateAsync` promise, or a `setTimeout`/`Time.SetTimeout`
    // firing an awaited promise, is stepped forward in the SAME frame. (An input
    // / on-load `dispatch` runs in worldSession.tickScripts BEFORE this tick, so
    // any promise it resolved is drained here too.) Cheap when idle:
    // hasPendingJob() short-circuits a scriptless/sync frame.
    //
    // BOUNDED so a chain that synchronously RE-QUEUES itself
    // (`Promise.resolve().then(function loop(){ Promise.resolve().then(loop); })`)
    // cannot hang the frame — bounded BOTH by `MAX_JOBS_PER_TICK` (total jobs) AND a
    // single-origin wall-clock `deadline` gating job STARTS.
    //
    // Drain ONE JOB AT A TIME. The cooperative-deadline interrupt,
    // when it fires INSIDE a promise-reaction job, becomes that job's REJECTION
    // (QuickJS: `executePendingJobs` "will not normally return errors thrown inside
    // async functions or rejected promises"). A batched pump arms ONE deadline
    // around a whole batch, so a LEGIT burst of `.then` reactions that merely
    // crosses the tick budget gets whichever reaction is executing turned into a
    // spurious rejection ("execution interrupted"). Draining one job per
    // iteration — checking the wall-clock BEFORE each start and arming a FRESH
    // per-job budget (a floor so a legit reaction near the edge always has time to
    // complete) — means the interrupt can only ever land inside a job that ITSELF
    // exceeds its budget (a genuine runaway → cut + reported), NEVER a legit reaction
    // that just happens to be running when the cumulative budget crosses. Surplus
    // jobs simply SPILL to the next tick. An infinite
    // self-requeue is bounded to `MAX_JOBS_PER_TICK` per tick (a few ms on RELEASE)
    // and resumes next frame. Cheap when idle: hasPendingJob() short-circuits.
    if (!disposed && runtime.hasPendingJob()) {
      // Single tick origin: the pump budget is `tickBudgetMs − elapsed`. But
      // give it a MINIMAL-PROGRESS FLOOR of at least MIN_JOB_BUDGET_MS even when
      // steps 1-2 already overran the budget — otherwise a world with a
      // budget-burning timer/interval EVERY tick would leave `Date.now() >=
      // tickStart + tickBudgetMs` at step-3 entry, the loop would run ZERO jobs, and
      // a legitimately-pending `await` would STARVE forever (an await spanning
      // ticks must still resolve). The floor adds at most ~MIN_JOB_BUDGET_MS to the
      // worst-case frame (still ~one tick budget + the per-job floor), NOT a fresh
      // full budget — so the single-origin bound holds.
      const deadline = Math.max(tickStart + tickBudgetMs, now() + MIN_JOB_BUDGET_MS);
      let remaining = MAX_JOBS_PER_TICK;
      while (!disposed && remaining > 0 && runtime.hasPendingJob() && now() < deadline) {
        // Each started job gets AT LEAST MIN_JOB_BUDGET_MS to complete (a legit
        // reaction is microseconds; only a self-runaway job exceeds this and is cut).
        armDeadline(Math.max(MIN_JOB_BUDGET_MS, deadline - now()));
        const jobs = runtime.executePendingJobs(1);
        if (jobs.error) {
          // A genuinely-runaway single job (cut by its per-job deadline) or a job
          // that threw surfaces here — report it (an async runaway IS a real error).
          reportCallbackError(describeError(context, jobs.error, '(pending-jobs)'));
          jobs.dispose();
          break;
        }
        const ran = typeof jobs.value === 'number' && jobs.value > 0 ? jobs.value : 0;
        jobs.dispose();
        remaining -= 1;
        if (ran === 0) break; // no forward progress — nothing more to drain
      }
    }
  };

  const dispose = (): void => {
    if (disposed) return;
    disposed = true;
    timers.clear();
    deferred.length = 0;
    // DRAIN the QuickJS pending-job queue BEFORE freeing the runtime.
    // A world with a large/unbounded pending job graph — e.g. a promise FANOUT
    // (`function fan(){ for(i<200) Promise.resolve().then(fan); }`) whose queue
    // grows faster than the per-tick pump drains it — otherwise trips a QuickJS
    // `assert(list_empty(&rt->gc_obj_list))` INSIDE `JS_FreeRuntime` (release WASM),
    // which THROWS out of dispose(). Since `worldSession.teardownWorld` calls
    // `sandbox.dispose()` FIRST and un-guarded, that throw would abort teardown —
    // leaking the world's Babylon scene/controller/registry and breaking the
    // navigation swap. The module survives an abort, but we must never THROW out of
    // dispose (host stays live), so the frees below are also guarded.
    //
    // Drain ONE JOB AT A TIME under an explicit WALL-CLOCK deadline
    // checked BEFORE EVERY JOB (mirroring the tick pump's per-job floor), NOT a
    // pass count of multi-job batches. A batch drain executes
    // every job in the batch to completion regardless of the interrupt handler — a
    // short reaction body never runs long enough to hit an interrupt checkpoint —
    // so a self-requeuing graph re-queues MORE jobs than each batch drains, growing
    // the backlog and burning unbounded wall time before the pass cap. Checking
    // `Date.now()` between every SINGLE job instead makes the drain's wall-clock
    // cost deterministic (~DISPOSE_DRAIN_BUDGET_MS) regardless of backlog size; a
    // residual queue past the budget is abandoned to the guarded frees below.
    try {
      runtime.setInterruptHandler(() => true);
      const drainDeadline = now() + DISPOSE_DRAIN_BUDGET_MS;
      let passes = MAX_DISPOSE_DRAIN_PASSES;
      while (
        passes-- > 0 &&
        runtime.alive &&
        runtime.hasPendingJob() &&
        now() < drainDeadline
      ) {
        const drained = runtime.executePendingJobs(1);
        // `drained.error` is DELIBERATELY ignored here (unlike the
        // tick pump, which reports it). A per-job interrupt-rejection here is
        // EXPECTED and not actionable during best-effort teardown; `drained.dispose()`
        // frees the handle (error or value) either way.
        drained.dispose();
      }
    } catch {
      /* best-effort drain — the guarded frees below are the safety net */
    }
    // Clear the interrupt handler so a stale deadline can't fire during teardown.
    if (runtime.alive) runtime.setInterruptHandler(() => false);
    for (const h of longLived) {
      if (!isIntrinsic(h) && h.alive) h.dispose();
    }
    longLived.length = 0;
    // Guard the frees: even after the drain, a pathologically deep pending graph
    // can still trip the JS_FreeRuntime assertion — swallow it (log) so dispose
    // NEVER throws into teardown (the module stays usable; a leaked runtime for a
    // malicious world is contained, benign worlds are unaffected).
    try {
      if (context.alive) context.dispose();
    } catch (e) {
      options.onLog?.(`[sandbox] context dispose failed: ${String(e)}`);
    }
    try {
      if (runtime.alive) runtime.dispose();
    } catch (e) {
      options.onLog?.(`[sandbox] runtime dispose failed: ${String(e)}`);
    }
  };

  return { runScript, evaluate, dispatch, expose, deferResume, tick, dispose };
}

/** Extract a plain-JSON ScriptError from a thrown/interrupt error handle. */
function describeError(
  context: QuickJSContext,
  errorHandle: QuickJSHandle,
  source: string,
): ScriptError {
  const dumped = context.dump(errorHandle) as unknown;
  // A cooperative-deadline interruption surfaces as an InterruptedError-class
  // error (name/message mention "interrupt"); flag it.
  let message = '';
  let stack: string | undefined;
  if (dumped && typeof dumped === 'object') {
    const obj = dumped as { name?: unknown; message?: unknown; stack?: unknown };
    const name = typeof obj.name === 'string' ? obj.name : '';
    message = typeof obj.message === 'string' ? obj.message : String(dumped);
    if (name && !message.startsWith(name)) message = `${name}: ${message}`;
    stack = typeof obj.stack === 'string' ? obj.stack : undefined;
  } else {
    message = String(dumped);
  }
  const interrupted = /interrupt/i.test(message);
  const error: ScriptError = { source, message: message || 'script error' };
  if (stack) error.stack = stack;
  if (interrupted) {
    error.interrupted = true;
    error.message = 'execution interrupted (deadline exceeded)';
  }
  return error;
}
