/**
 * QuickJS sandbox chunk. THE CODE-SPLIT CHUNK.
 *
 * This is the ONLY import site for the QuickJS WASM VARIANT
 * (`@jitl/quickjs-singlefile-browser-release-sync`). It MUST be reached ONLY
 * via a dynamic `import()` (worldSession's default `SandboxLoader` is
 * `() => import('../sandbox/sandboxChunk')`): a STATIC import of this module
 * from any main-bundle module would pull the ~1 MB QuickJS WASM stack into the
 * first-paint bundle and blow the first-paint budget — with NO test going red
 * (the shader-import lint is Babylon-specific and does not cover QuickJS). The
 * GUARDS are the e2e both-directions chunk-fetch assertion (a scripted world
 * fetches this chunk; a scriptless world does NOT) + the bundle budget + code
 * review. A scriptless world never loads it.
 *
 * The `singlefile-browser-release-sync` variant embeds the WASM as base64 in
 * the ESModule — so there is NO separate `.wasm` asset to resolve, NO CDN
 * fetch, and it instantiates SAME-ORIGIN, offline, and headless with zero Vite
 * config (contrast Havok, which resolves its `.wasm` via import.meta.url). The
 * `sync` type gives SYNCHRONOUS host calls (the whole reason for QuickJS over a
 * Worker). Module construction is the ONE async step (WASM
 * instantiation), confined to `createSandbox` (chunk-load time); `tick`/
 * `runScript` stay synchronous.
 */
import {
  newQuickJSWASMModuleFromVariant,
  type QuickJSWASMModule,
} from 'quickjs-emscripten-core';
import variant from '@jitl/quickjs-singlefile-browser-release-sync';
import { createSandboxFromModule } from './sandboxCore';
import type { Sandbox, SandboxOptions } from './sandboxTypes';

/**
 * The QuickJS WASM module is expensive to build (WASM instantiation) and is
 * SHARED across worlds — one per chunk load. Each world still gets a FRESH
 * runtime+context (a fresh sandbox) from this shared module. Cached as a
 * promise so concurrent loads await the same instantiation.
 */
let modulePromise: Promise<QuickJSWASMModule> | undefined;

function getModule(): Promise<QuickJSWASMModule> {
  if (!modulePromise) {
    modulePromise = newQuickJSWASMModuleFromVariant(variant);
  }
  return modulePromise;
}

/**
 * Create a fresh sandbox (one per world). Awaits the shared module (WASM
 * instantiation on first call), then builds an isolated runtime+context.
 */
export async function createSandbox(options?: SandboxOptions): Promise<Sandbox> {
  const module = await getModule();
  return createSandboxFromModule(module, options);
}
